/* ============================================================================
 * Winky Community - Game Plugin: Jan Ken Pon
 * Loaded on demand by the core (classic script, shares global scope: can use
 * el/App/T/rest/insert/toast/views/charById directly).
 *
 * Styling: the shared arcade 'chrome' CSS (jkptop/pips/jkpx/jkpend/timer, the
 * fighter classes and the character picker) lives in the CORE stylesheet, so
 * no CSS is injected here.
 *
 * CROSSPLAY CONTRACT (DO NOT CHANGE): writes the shared `game_challenges` table
 * with from_char = character id; round / from_move / to_move / from_score /
 * to_score keep their meaning. The smartwatch client relies on this exact
 * schema, so cross-device play keeps working.
 * ==========================================================================*/
// Jan Ken Pon voice (real human voice, CC-BY-SA tomoharu yugetsu / yugetsu-sounds.com)
const JKP_VOICE_URI='data:audio/mpeg;base64,';
let JKP_AUDIO=null;
function jkpPlayVoice(){ try{ if(!JKP_AUDIO){ JKP_AUDIO=new Audio(JKP_VOICE_URI); JKP_AUDIO.preload='auto'; } JKP_AUDIO.currentTime=0; const p=JKP_AUDIO.play(); if(p&&p.catch)p.catch(()=>{}); }catch(e){} }
const GAME_CHARS=[
{id:'oni',jp:'鬼',en:'Oni',img:'data:image/png;base64,'},
{id:'kunoichi',jp:'くノ一',en:'Kunoichi',img:'data:image/png;base64,'},
{id:'samurai',jp:'侍',en:'Samurai',img:'data:image/png;base64,'},
{id:'ninja',jp:'忍',en:'Ninja',img:'data:image/png;base64,'},
{id:'monk',jp:'僧',en:'Monk',img:'data:image/png;base64,'},
{id:'sumo',jp:'力士',en:'Sumo',img:'data:image/png;base64,'},
];
function charById(id){ for(const c of GAME_CHARS){ if(c.id===id) return c; } return GAME_CHARS[0]; }
const JKP_RULES={ rock:'scissors', scissors:'paper', paper:'rock' }; // key beats value
const JKP_HAND={ rock:'✊', paper:'✋', scissors:'✌️' };
const JKP_JP={ rock:'グー', paper:'パー', scissors:'チョキ' };
// ---- Character picker + send challenge ----
async function openGameChallenge(threadId, otherId, otherNick){
  const bg=el('div','modal-bg'); const md=el('div','modal'); md.style.width='min(96%,460px)';
  md.appendChild(el('div',null,'🥋 じゃんけん — '+T('chooseFighter')));
  md.appendChild(el('div','spacer'));
  const grid=el('div','charpick'); md.appendChild(grid);
  let sel=null;
  GAME_CHARS.forEach(c=>{ const cell=el('div','cc'); const im=document.createElement('img'); im.src=c.img; cell.appendChild(im); const jp=el('div','jp',c.jp); const en=el('div','en',c.en); cell.appendChild(jp); cell.appendChild(en); cell.onclick=()=>{ sel=c.id; grid.querySelectorAll('.cc').forEach(x=>x.classList.remove('sel')); cell.classList.add('sel'); }; grid.appendChild(cell); });
  const acts=el('div','actions');
  const ok=el('button','btn green',T('challengeBtn'));
  ok.onclick=async()=>{ if(!sel){ toast(T('chooseFighter')); return; } bg.remove();
    try{ const row=await insert('/game_challenges',{thread_id:threadId,from_id:App.me.id,from_nick:App.me.nickname,to_id:otherId,to_nick:otherNick,from_char:sel,status:'pending',round:1,from_score:0,to_score:0}); const ch=row&&row.length?row[0]:null; if(ch){ App.go('jkpGame',{id:ch.id,role:'from',myChar:sel,otherNick:otherNick}); } }catch(e){ toast('Error: '+e.message); }
  };
  const cl=el('button','btn dark',T('cancel')); cl.onclick=()=>bg.remove();
  acts.appendChild(ok); acts.appendChild(cl); md.appendChild(acts);
  bg.appendChild(md); document.body.appendChild(bg);
}
// ---- Accept an incoming challenge: pick a fighter ----
async function acceptGameChallenge(ch){
  const bg=el('div','modal-bg'); const md=el('div','modal'); md.style.width='min(96%,460px)';
  md.appendChild(el('div',null,'🥋 '+ch.from_nick+' — '+T('chooseFighter')));
  md.appendChild(el('div','spacer'));
  const grid=el('div','charpick'); md.appendChild(grid);
  let sel=null;
  GAME_CHARS.forEach(c=>{ const cell=el('div','cc'); const im=document.createElement('img'); im.src=c.img; cell.appendChild(im); cell.appendChild(el('div','jp',c.jp)); cell.appendChild(el('div','en',c.en)); cell.onclick=()=>{ sel=c.id; grid.querySelectorAll('.cc').forEach(x=>x.classList.remove('sel')); cell.classList.add('sel'); }; grid.appendChild(cell); });
  const acts=el('div','actions');
  const ok=el('button','btn green',T('accept'));
  ok.onclick=async()=>{ if(!sel){ toast(T('chooseFighter')); return; } bg.remove();
    try{ await rest('/game_challenges?id=eq.'+ch.id,{method:'PATCH',body:{to_char:sel,status:'active',round:1,updated_at:new Date().toISOString()}}); App.go('jkpGame',{id:ch.id,role:'to',myChar:sel,otherNick:ch.from_nick}); }catch(e){ toast('Error'); }
  };
  const cl=el('button','btn dark',T('cancel')); cl.onclick=()=>bg.remove();
  acts.appendChild(ok); acts.appendChild(cl); md.appendChild(acts);
  bg.appendChild(md); document.body.appendChild(bg);
}
// ---- The arena view ----
views.jkpGame=function(p){
  App.setHeader('じゃんけん',{back:true});
  const m=App.main(); m.classList.remove('chatview');
  const root=el('div','jkp');
  root.innerHTML='<div class="jkpsky"></div><div class="jkpfloor"></div>';
  const xb=el('button','jkpx','✕'); xb.onclick=()=>{ finishExit(); }; root.appendChild(xb);
  const muteBtn=el('button','jkpx'); muteBtn.style.right='54px'; root.appendChild(muteBtn);
  const setMuteIcon=()=>{ muteBtn.textContent = muted?'🔇':'🔊'; };
  muteBtn.onclick=()=>{ muted=!muted; LS.set('wc_jkpmute',muted?'1':'0'); setMuteIcon(); if(!muted){ jkpPlayVoice(); setTimeout(()=>{ try{ if(JKP_AUDIO){ JKP_AUDIO.pause(); JKP_AUDIO.currentTime=0; } }catch(e){} },60); } };
  // top bar
  const top=el('div','jkptop');
  const sideL=el('div','side l'); const pnL=el('div','pn'); const pipsL=el('div','pips'); sideL.appendChild(pnL); sideL.appendChild(pipsL);
  const rnd=el('div','rnd','ROUND 1');
  const sideR=el('div','side r'); const pnR=el('div','pn'); const pipsR=el('div','pips'); sideR.appendChild(pnR); sideR.appendChild(pipsR);
  top.appendChild(sideL); top.appendChild(rnd); top.appendChild(sideR); root.appendChild(top);
  // timer
  const timer=el('div','jkptimer'); const tfill=el('i'); timer.appendChild(tfill); root.appendChild(timer);
  // arena
  const arena=el('div','jkparena');
  const fL=el('div','jkpfighter left'); const handL=el('div','jkphand'); const imgL=document.createElement('img'); fL.appendChild(handL); fL.appendChild(imgL);
  const fR=el('div','jkpfighter right'); const handR=el('div','jkphand'); const imgR=document.createElement('img'); fR.appendChild(handR); fR.appendChild(imgR);
  arena.appendChild(fL); arena.appendChild(fR); root.appendChild(arena);
  // call + result overlays
  const call=el('div','jkpcall'); const callSpan=el('span'); call.appendChild(callSpan); root.appendChild(call);
  const resultOv=el('div','jkpresult'); root.appendChild(resultOv);
  // moves
  const moves=el('div','jkpmoves');
  const mkMove=(k)=>{ const b=el('button'); b.innerHTML='<span class="em">'+JKP_HAND[k]+'</span><span class="jp">'+JKP_JP[k]+'</span>'; b.dataset.k=k; b.addEventListener('contextmenu',e=>e.preventDefault()); b.onclick=()=>pickMove(k); return b; };
  const bRock=mkMove('rock'), bPaper=mkMove('paper'), bScissors=mkMove('scissors');
  moves.appendChild(bRock); moves.appendChild(bPaper); moves.appendChild(bScissors); root.appendChild(moves);
  const wait=el('div','jkpwait'); wait.style.display='none'; root.appendChild(wait);
  const endOv=el('div','jkpend'); endOv.style.display='none'; root.appendChild(endOv);
  m.appendChild(root);

  // I am 'from' or 'to'
  const meFrom = p.role==='from';
  // left = me, right = opponent (visually)
  let ch=null; let curRound=0; let myMove=null; let animating=false; let resolvedRound=0; let phaseResolved=false; let ended=false;
  let muted=LS.get('wc_jkpmute','')==='1';
  let tLeft=15; let tInt=null; let poll=null;

  // Pose helper: set inline animation on a fighter img (mirror baked into R keyframes).
  const setPose=(imgEl,side,pose)=>{ // side 'L'|'R', pose 'idle'|'windup'|'shoot'|'win'|'lose'|'none'
    const map={ idle:['jkiL 1s ease-in-out infinite','jkiR 1s ease-in-out infinite'],
      windup:['jkwL .45s ease-in-out infinite','jkwR .45s ease-in-out infinite'],
      shoot:['jksL .5s ease','jksR .5s ease'],
      win:['jkwinL .5s ease-in-out infinite','jkwinR .5s ease-in-out infinite'],
      lose:['jkloseL .5s ease forwards','jkloseR .5s ease forwards'],
      none:['none','none'] };
    const a=map[pose]||map.idle; imgEl.style.animation = (side==='R')?a[1]:a[0];
  };
  const idlePose=()=>{ setPose(imgL,'L','idle'); setPose(imgR,'R','idle'); };
  const myChar=charById(p.myChar); imgL.src=myChar.img; pnL.textContent=(App.me.nickname||'You');
  imgR.src=charById('samurai').img; pnR.textContent=(p.otherNick||'?');

  const setPips=(myScore,opScore)=>{ const draw=(a,box)=>{ box.innerHTML=''; for(let i=0;i<3;i++){ const s=el('span','pip'+(i<a?' on':'')); box.appendChild(s);} }; draw(myScore,pipsL); draw(opScore,pipsR); };
  const myScoreOf=(r)=> meFrom? r.from_score : r.to_score;
  const opScoreOf=(r)=> meFrom? r.to_score : r.from_score;
  const myMoveField=()=> meFrom?'from_move':'to_move';
  const myMoveOf=(r)=> meFrom? r.from_move : r.to_move;
  const opMoveOf=(r)=> meFrom? r.to_move : r.from_move;

  const startTimer=()=>{ stopTimer(); tLeft=15; tfill.style.width='100%'; tInt=setInterval(()=>{ tLeft-=0.25; if(tLeft<=0){ tLeft=0; tfill.style.width='0%'; stopTimer(); if(!myMove && !animating && !ended){ const arr=['rock','paper','scissors']; pickMove(arr[Math.floor(Math.random()*3)]); } } else { tfill.style.width=(tLeft/15*100)+'%'; } },250); App.poll2=tInt; };
  const stopTimer=()=>{ if(tInt){ clearInterval(tInt); if(App.poll2===tInt)App.poll2=null; tInt=null; } };

  const setMovesEnabled=(on)=>{ [bRock,bPaper,bScissors].forEach(b=>{ b.disabled=!on; b.classList.remove('sel'); }); moves.style.display=on?'flex':'none'; wait.style.display=on?'none':'block'; if(!on){ wait.textContent=T('waitOpponent'); } };

  // Show my chosen hand immediately + windup arm animation (opponent stays hidden).
  function showMyHand(k){ if(!k)return; handL.textContent=JKP_HAND[k]; handL.classList.add('ready'); setPose(imgL,'L','windup'); }
  async function pickMove(k){ if(myMove||animating||ended) return;
    // Unlock audio on first user gesture (browser autoplay policy).
    try{ if(!JKP_AUDIO){ JKP_AUDIO=new Audio(JKP_VOICE_URI); } JKP_AUDIO.play().then(()=>{ JKP_AUDIO.pause(); JKP_AUDIO.currentTime=0; }).catch(()=>{}); }catch(e){}
    myMove=k; [bRock,bPaper,bScissors].forEach(b=>{ if(b.dataset.k===k)b.classList.add('sel'); b.disabled=true; }); stopTimer(); showMyHand(k); wait.style.display='block'; wait.textContent=T('waitOpponent'); moves.style.display='none';
    try{ const body={updated_at:new Date().toISOString()}; body[myMoveField()]=k; await rest('/game_challenges?id=eq.'+p.id,{method:'PATCH',body}); }catch(e){}
    // reflect my hand immediately (hidden until reveal)
  }

  function playCall(cb){ animating=true; if(!muted) jkpPlayVoice(); const beats=['じゃん','けん','ぽん!']; let i=0; const step=()=>{ if(i>=beats.length){ callSpan.classList.remove('show'); cb(); return; } callSpan.textContent=beats[i]; callSpan.classList.remove('show'); void callSpan.offsetWidth; callSpan.classList.add('show'); i++; setTimeout(step,560); }; step(); }

  function showHands(myK,opK){ handL.classList.remove('ready'); handR.classList.remove('ready'); handL.textContent=JKP_HAND[myK]; handR.textContent=JKP_HAND[opK]; void handL.offsetWidth; handL.style.animation='jkppop .25s ease'; handR.style.animation='jkppop .25s ease'; setPose(imgL,'L','shoot'); setPose(imgR,'R','shoot'); setTimeout(()=>{ idlePose(); },600); }
  function clearHands(){ handL.textContent=''; handR.textContent=''; handL.classList.remove('ready'); handR.classList.remove('ready'); idlePose(); }

  function roundOutcome(myK,opK){ if(myK===opK) return 'draw'; return (JKP_RULES[myK]===opK)?'win':'lose'; }

  async function resolveRound(r){
    const myK=myMoveOf(r), opK=opMoveOf(r); if(!myK||!opK) return;
    resolvedRound=r.round; phaseResolved=true; animating=true; stopTimer(); setMovesEnabled(false);
    playCall(()=>{
      showHands(myK,opK);
      const res=roundOutcome(myK,opK);
      setTimeout(()=>{
        resultOv.innerHTML=''; const sp=el('span',null, res==='win'?'勝!':(res==='lose'?'敗':'あいこ')); resultOv.appendChild(sp);
        fL.classList.remove('lose'); fR.classList.remove('lose');
        fL.classList.remove('lose'); fR.classList.remove('lose');
        if(res==='win'){ setPose(imgL,'L','win'); setPose(imgR,'R','lose'); fR.classList.add('lose'); } else if(res==='lose'){ setPose(imgR,'R','win'); setPose(imgL,'L','lose'); fL.classList.add('lose'); }
        setTimeout(async()=>{
          resultOv.innerHTML=''; clearHands(); fL.classList.remove('lose'); fR.classList.remove('lose'); idlePose();
          // Authority (from) writes the new scores / round / clears moves.
          if(meFrom){
            let fs=r.from_score, ts=r.to_score; if(res!=='draw'){ if(res==='win') fs++; else ts++; }
            const nextRound=(res==='draw')? r.round : r.round+1;
            let winner=null,status='active';
            if(fs>=2 || ts>=2 || nextRound>3){ status='finished'; winner = fs>ts? p.__fromId : (ts>fs? p.__toId : 0); }
            try{ await rest('/game_challenges?id=eq.'+p.id,{method:'PATCH',body:{from_score:fs,to_score:ts,round:(status==='finished'?r.round:nextRound),from_move:null,to_move:null,winner:winner,status:status,updated_at:new Date().toISOString()}}); }catch(e){}
          }
          animating=false; myMove=null;
          // NOTE: do NOT re-enable here. The host clears both moves in the DB,
          // and the next tick's fresh-phase check (!myK && !opK) re-opens the
          // round for BOTH players — including draws. Re-enabling here caused a
          // double resolution because the DB still briefly held both moves.
        },1100);
      },1000);
    });
  }

  let rematchPoll=null; let rematchShown=0;
  function renderEnd(r){
    const iWon = (r.winner===App.me.id); const draw=(r.winner===0||r.winner==null);
    endOv.innerHTML=''; const big=el('div','big '+(draw?'draw':(iWon?'win':'lose')), draw?'DRAW':(iWon?'YOU WIN!':'YOU LOSE'));
    const jp=el('div',null, draw?'引き分け':(iWon?'勝利!':'敗北')); jp.style.fontFamily="'Noto Sans JP',sans-serif"; jp.style.fontSize='7vw'; jp.style.marginTop='-8px'; jp.style.textShadow='3px 3px 0 #000';
    endOv.appendChild(big); endOv.appendChild(jp);
    const row=el('div'); row.style.display='flex'; row.style.gap='12px';
    const again=el('button','green',T('rematch')); again.onclick=()=>{ stopRematchPoll(); App.back(); setTimeout(()=>openGameChallenge(p.__threadId,(meFrom?p.__toId:p.__fromId),p.otherNick),150); };
    const back=el('button',null,T('exit')); back.onclick=()=>{ stopRematchPoll(); App.back(); };
    row.appendChild(again); row.appendChild(back); endOv.appendChild(row); endOv.style.display='flex';
  }
  function renderRematchIncoming(nc){
    endOv.innerHTML='';
    const t=el('div','big win','⚔️'); t.style.fontSize='16vw'; endOv.appendChild(t);
    const msg=el('div',null, (nc.from_nick||p.otherNick)+' '+T('rematchIncoming')); msg.style.fontSize='10px'; msg.style.textAlign='center'; msg.style.textShadow='2px 2px 0 #000'; endOv.appendChild(msg);
    const row=el('div'); row.style.display='flex'; row.style.gap='12px';
    const acc=el('button','green',T('accept')); acc.onclick=()=>{ stopRematchPoll(); App.back(); setTimeout(()=>acceptGameChallenge(nc),150); };
    const dec=el('button',null,T('reject')); dec.onclick=async()=>{ try{ await rest('/game_challenges?id=eq.'+nc.id,{method:'PATCH',body:{status:'declined',updated_at:new Date().toISOString()}}); }catch(e){} rematchShown=0; renderEnd(ch); };
    row.appendChild(acc); row.appendChild(dec); endOv.appendChild(row);
  }
  function stopRematchPoll(){ if(rematchPoll){ clearInterval(rematchPoll); rematchPoll=null; } }
  function showEnd(r){ ended=true; App.stopPoll(); setMovesEnabled(false); wait.style.display='none';
    renderEnd(r);
    // Keep listening for a rematch challenge FROM the opponent (so it appears
    // right here in the game screen, not only in the DM).
    const oppId = meFrom? p.__toId : p.__fromId;
    stopRematchPoll();
    rematchPoll=setInterval(async()=>{
      try{ const rows=await rest('/game_challenges?to_id=eq.'+App.me.id+'&from_id=eq.'+oppId+'&status=eq.pending&order=id.desc&limit=1'); const nc=rows&&rows.length?rows[0]:null;
        if(nc && nc.id!==p.id){ if(rematchShown!==nc.id){ rematchShown=nc.id; renderRematchIncoming(nc); } }
        else { if(rematchShown){ rematchShown=0; renderEnd(ch); } }
      }catch(e){}
    },1500);
    App.poll2=rematchPoll; // so App.stopPoll on navigation clears it
  }

  async function finishExit(){ App.stopPoll(); try{ if(!ended){ await rest('/game_challenges?id=eq.'+p.id,{method:'PATCH',body:{status:'finished',winner:(meFrom?p.__toId:p.__fromId),updated_at:new Date().toISOString()}}); } }catch(e){} App.back(); }

  async function tick(){
    try{ const rows=await rest('/game_challenges?id=eq.'+p.id+'&select=*'); const r=rows&&rows.length?rows[0]:null; if(!r){ return; } ch=r;
      p.__fromId=r.from_id; p.__toId=r.to_id; p.__threadId=r.thread_id;
      // opponent char
      const opId = meFrom? r.to_char : r.from_char; if(opId){ imgR.src=charById(opId).img; }
      pnR.textContent = meFrom? (r.to_nick||p.otherNick) : (r.from_nick||p.otherNick);
      setPips(myScoreOf(r), opScoreOf(r)); rnd.textContent='ROUND '+Math.min(r.round,3);
      if(r.status==='declined'){ if(!ended){ ended=true; toast(T('declinedGame')); setTimeout(()=>App.back(),800);} return; }
      if(r.status==='finished'){ if(!ended) showEnd(r); return; }
      if(r.status!=='active'){ wait.style.display='block'; wait.textContent=T('waitAccept'); moves.style.display='none'; return; }
      // active
      const myK=myMoveOf(r), opK=opMoveOf(r);
      if(r.round!==curRound){ curRound=r.round; myMove=null; animating=false; phaseResolved=false; clearHands(); resultOv.innerHTML=''; }
      // FRESH PHASE: both moves cleared by host (start of match or after a
      // resolved round, including DRAWS where round stays the same). Re-enable.
      if(!myK && !opK && !animating && !ended){
        if(phaseResolved || myMove!==null || moves.style.display!=='flex'){
          phaseResolved=false; myMove=null; clearHands(); resultOv.innerHTML='';
          setMovesEnabled(true); startTimer();
        }
      }
      // Server confirms MY move -> keep disabled + show my chosen hand.
      if(myK){ if(myMove!==myK){ myMove=myK; } setMovesEnabled(false); showMyHand(myK); }
      // I picked, waiting for opponent.
      if(myK && !opK && !animating){ wait.style.display='block'; wait.textContent=T('waitOpponent'); moves.style.display='none'; }
      // Both picked -> resolve this phase once.
      if(myK && opK && !animating && !phaseResolved){ resolveRound(r); }
    }catch(e){}
  }

  idlePose(); setMuteIcon();
  setMovesEnabled(false); wait.style.display='block'; wait.textContent = meFrom? T('waitAccept'): T('getReady');
  App.stopPoll();
  tick(); App.poll=setInterval(tick,1000);
};

/* ---- register with the core so it can open/accept challenges & draw icons ---- */
if(window.WinkyGames){ WinkyGames.register({
  id:'jankenpon',
  openChallenge:function(threadId,otherId,otherNick){ return openGameChallenge(threadId,otherId,otherNick); },
  acceptChallenge:function(ch){ return acceptGameChallenge(ch); },
  challengeIcon:function(ch){ var c=charById(ch.from_char); var im=document.createElement('img'); im.src=c.img; return im; }
}); }
